"use client";

export * from "./context";
export * from "./identity";
export * from "./runtime-user-sync";
export * from "./types";

"use client";

import { createContext, useContext, type ReactNode } from "react";
import { AOMI_AUTH_DISCONNECTED_IDENTITY } from "./identity";
import type { AomiAuthAdapter } from "./types";

const DISCONNECTED_ADAPTER: AomiAuthAdapter = {
  identity: AOMI_AUTH_DISCONNECTED_IDENTITY,
  isReady: true,
  isSwitchingChain: false,
  canConnect: false,
  canOpenAccountUI: false,
  canDisconnect: false,
  connect: async () => undefined,
};

const AomiAuthAdapterContext =
  createContext<AomiAuthAdapter>(DISCONNECTED_ADAPTER);

export function AomiAuthAdapterProvider({
  children,
  value,
}: {
  children: ReactNode;
  value: AomiAuthAdapter;
}) {
  return (
    <AomiAuthAdapterContext.Provider value={value}>
      {children}
    </AomiAuthAdapterContext.Provider>
  );
}

export function useAomiAuthAdapter(): AomiAuthAdapter {
  return useContext(AomiAuthAdapterContext);
}

"use client";

import type { Chain } from "viem";
import type {
  WalletEip712Payload,
  WalletSolanaSignPayload,
  WalletTxPayload,
} from "@aomi-labs/react";

export type AomiAuthStatus = "booting" | "disconnected" | "connected";

export type AomiAuthIdentity = {
  status: AomiAuthStatus;
  isConnected: boolean;
  /** Connected EVM wallet address (0x...). */
  address?: string;
  chainId?: number;
  /**
   * Connected SVM (Solana) wallet pubkey, base58. Independent of
   * `address` — a Para-backed session can carry both an EVM and a
   * Solana wallet under one identity.
   */
  svmAddress?: string;
  authProvider?: string;
  primaryLabel: string;
  secondaryLabel?: string;
  /**
   * Set when the connected wallet itself IS a smart account (always-AA),
   * e.g. Base Account / Coinbase Smart Wallet. Leave undefined for EOA
   * wallets that may opt into AA per-transaction (Para's 7702/4337 flows).
   */
  aaMode?: "4337" | "7702";
  smartAccount?: string;
};

export type AomiTxResult = {
  txHash: string;
  amount?: string;
  aaRequestedMode?: "4337" | "7702" | "none";
  aaResolvedMode?: "4337" | "7702" | "none";
  aaFallbackReason?: string;
  executionKind?: string;
  batched?: boolean;
  callCount?: number;
  sponsored?: boolean;
  SmartAccount4337?: string;
  Delegation7702?: string;
};

export type AomiAuthAdapter = {
  identity: AomiAuthIdentity;
  isReady: boolean;
  isSwitchingChain: boolean;

  canConnect: boolean;
  canOpenAccountUI: boolean;
  canDisconnect: boolean;

  supportedChains?: readonly Chain[];

  connect: () => Promise<void>;
  openAccountUI?: () => Promise<void>;
  disconnect?: () => Promise<void>;

  switchChain?: (chainId: number) => Promise<void>;

  sendTransaction?: (payload: WalletTxPayload) => Promise<AomiTxResult>;
  signTypedData?: (
    payload: WalletEip712Payload,
  ) => Promise<{ signature: string }>;
  /**
   * Sign a Solana transaction with the user's wallet. Singular and
   * sign-only — apps submit the returned signed tx through their own
   * RPC. The host doesn't decode or broadcast Solana txs.
   *
   * `payload.unsignedTx` is base64 of `VersionedTransaction.serialize()`
   * (legacy `Transaction` is also acceptable). Implementations should
   * try the versioned-tx path first and fall back to legacy on
   * deserialization failure, mirroring what wallet adapters do.
   *
   * Optional like `signTypedData` — adapters that don't support Solana
   * (e.g. base-account) leave it undefined; `RuntimeTxHandler` rejects
   * the request with a "Solana wallet provider is not ready" error in
   * that case.
   */
  signSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signedTx: string }>;
};

"use client";

import type { AomiAuthIdentity } from "./types";

export const AOMI_AUTH_DISCONNECTED_IDENTITY: AomiAuthIdentity = {
  status: "disconnected",
  isConnected: false,
  address: undefined,
  chainId: undefined,
  svmAddress: undefined,
  authProvider: undefined,
  primaryLabel: "Not connected",
  secondaryLabel: undefined,
};

export const AOMI_AUTH_BOOTING_IDENTITY: AomiAuthIdentity = {
  status: "booting",
  isConnected: false,
  address: undefined,
  chainId: undefined,
  svmAddress: undefined,
  authProvider: undefined,
  primaryLabel: "Loading Wallet...",
  secondaryLabel: undefined,
};

export function formatAddress(address?: string): string | undefined {
  if (!address) return undefined;
  return `${address.slice(0, 5)}..${address.slice(-2)}`;
}

export function formatAuthProvider(provider?: string): string | undefined {
  if (!provider) return undefined;

  const labelMap: Record<string, string> = {
    google: "Google",
    github: "GitHub",
    apple: "Apple",
    facebook: "Facebook",
    x: "X",
    discord: "Discord",
    farcaster: "Farcaster",
    telegram: "Telegram",
    email: "Email",
    phone: "Phone",
    wallet: "Wallet",
    baseAccount: "Base Account",
  };

  return labelMap[provider] ?? provider;
}

export function inferAuthProvider(authMethods: unknown): string | undefined {
  if (!(authMethods instanceof Set) || authMethods.size === 0) return undefined;

  const allowed = new Set([
    "google",
    "github",
    "apple",
    "facebook",
    "x",
    "discord",
    "farcaster",
    "telegram",
    "email",
    "phone",
  ]);

  for (const method of authMethods) {
    if (typeof method !== "string") continue;
    const normalized = method.toLowerCase();
    if (allowed.has(normalized)) return normalized;
  }

  const first = authMethods.values().next().value;
  return typeof first === "string" ? first.toLowerCase() : undefined;
}

"use client";

import { useEffect } from "react";
import { useUser } from "@aomi-labs/react";
import { useAomiAuthAdapter } from "./context";
import { formatAuthProvider } from "./identity";

/**
 * Bridge that pushes the active auth adapter's identity into the
 * SDK-level `useUser()` state every time it changes. The SDK's
 * `UserState` carries `svmAddress` independently of the EVM `address`,
 * so a multi-chain provider (e.g. Para with both EVM and Solana
 * connectors) can populate both — the backend's call envelope reads
 * each from its respective `domain.evm.address` / `domain.svm.address`
 * attribute.
 */
export function AomiAuthRuntimeUserSync() {
  const adapter = useAomiAuthAdapter();
  const { setUser, addExtValue, removeExtValue } = useUser();
  const identity = adapter.identity;
  const providerLabel =
    identity.secondaryLabel ?? formatAuthProvider(identity.authProvider);

  useEffect(() => {
    setUser({
      address: identity.address ?? undefined,
      chainId: identity.chainId ?? undefined,
      isConnected: identity.isConnected,
      svmAddress: identity.svmAddress ?? undefined,
      // Pass `null` (not undefined) when the connected wallet isn't a
      // smart account, so switching from a smart-account provider
      // (Base Account) to an EOA provider (Para) clears the stale flag
      // instead of being pruned as a no-op.
      aaMode: identity.isConnected ? (identity.aaMode ?? null) : null,
      smartAccount: identity.isConnected
        ? (identity.smartAccount ?? null)
        : null,
    });
  }, [
    identity.aaMode,
    identity.address,
    identity.chainId,
    identity.isConnected,
    identity.smartAccount,
    identity.svmAddress,
    setUser,
  ]);

  useEffect(() => {
    if (identity.isConnected && identity.authProvider) {
      addExtValue("wallet_provider", identity.authProvider);
    } else {
      removeExtValue("wallet_provider");
    }

    if (identity.isConnected && providerLabel) {
      addExtValue("wallet_provider_label", providerLabel);
    } else {
      removeExtValue("wallet_provider_label");
    }
  }, [
    addExtValue,
    identity.authProvider,
    identity.isConnected,
    providerLabel,
    removeExtValue,
  ]);

  return null;
}

export * from "./aomi-auth-adapter/identity";
export type {
  AomiAuthIdentity,
  AomiAuthStatus,
} from "./aomi-auth-adapter/types";
